  "pravachanam-bhagavatam": { kind: "article", category: { en: "Pravachanamulu", te: "ప్రవచనములు" }, title: { en: "Srimad Bhagavatam", te: "శ్రీమద్భాగవతం" }, subtitle: { en: "A devotional journey through the stories and teachings of the Bhagavatam.", te: "భాగవతంలోని కథలు, బోధనల ద్వారా భక్తి ప్రస్థానం." }, sections: [{ title: { en: "About this collection", te: "ఈ సేకరణ గురించి" }, paragraphs: [{ en: "Brahmasri Vaddiparti Padmakar is known for delivering Bhagavata discourses from memory. Explore the available talks and related resources through the Peetham's discourse collection.", te: "బ్రహ్మశ్రీ వద్దిపర్తి పద్మాకర్ గారు భాగవత ప్రవచనాలను ధారణతో అందించడంలో ప్రసిద్ధి. పీఠం ప్రవచన సేకరణలో అందుబాటులో ఉన్న ప్రసంగాలు, సంబంధిత వనరులను చూడండి." }] }], related: ["pravachanalu", "books", "stotras"] },
  "pravachanam-devi": { kind: "article", category: { en: "Pravachanamulu", te: "ప్రవచనములు" }, title: { en: "Devi Bhagavatam", te: "దేవీ భాగవతం" }, subtitle: { en: "The sacred narratives and wisdom of the Divine Mother.", te: "జగన్మాత పవిత్ర కథలు, జ్ఞానం." }, sections: [{ title: { en: "A beloved text", te: "ప్రియమైన గ్రంథం" }, paragraphs: [{ en: "The Devi Bhagavatam is among the eighteen Mahapuranas. This section gathers the Peetham's study and reading resources connected with Devi Bhagavatam.", te: "దేవీ భాగవతం అష్టాదశ మహాపురాణాల్లో ఒకటి. ఈ విభాగంలో దేవీ భాగవతానికి సంబంధించిన పీఠం అధ్యయన, పఠన వనరులు ఉన్నాయి." }] }], related: ["pravachanalu", "devi-ebook", "stotras"] },
  "pravachanam-ramayana": { kind: "article", category: { en: "Pravachanamulu", te: "ప్రవచనములు" }, title: { en: "Ramayanam", te: "రామాయణం" }, subtitle: { en: "Listen and reflect on the Ramayana's teachings of dharma and devotion.", te: "రామాయణ ధర్మం, భక్తి బోధనలను విని, ఆలోచించండి." }, sections: [{ title: { en: "The story and its teachings", te: "కథ, దాని బోధనలు" }, paragraphs: [{ en: "Explore discourse resources and recitation materials inspired by the Ramayana. The collection includes story-based teachings and sloka recitations.", te: "రామాయణ ప్రేరణతో రూపొందిన ప్రవచనాలు, పారాయణ వనరులను చూడండి. కథా బోధనలు, శ్లోక పారాయణాలు ఇందులో ఉన్నాయి." }] }], related: ["pravachanalu", "slokalu", "books"] },
  "pravachanam-puranas": { kind: "article", category: { en: "Pravachanamulu", te: "ప్రవచనములు" }, title: { en: "Ashtadasa Puranas", te: "అష్టాదశ పురాణాలు" }, subtitle: { en: "An introduction to the eighteen Puranas traditionally attributed to Vedavyasa.", te: "వేదవ్యాస మహర్షికి ఆపాదించబడిన అష్టాదశ పురాణాల పరిచయం." }, sections: [{ title: { en: "A treasury of knowledge", te: "జ్ఞాన నిధి" }, paragraphs: [{ en: "The Puranas preserve stories, teachings, sacred histories and reflections on dharma. Brahmasri Padmakar has delivered discourses on all eighteen Puranas.", te: "పురాణాలు కథలు, బోధనలు, పవిత్ర చరిత్రలు, ధర్మంపై ఆలోచనలను సంరక్షిస్తాయి. బ్రహ్మశ్రీ పద్మాకర్ గారు అష్టాదశ పురాణాలపై ప్రవచనాలు అందించారు." }] }], related: ["pravachanalu", "books", "journal"] },
  "pravachanam-mahabharata": { kind: "article", category: { en: "Pravachanamulu", te: "ప్రవచనములు" }, title: { en: "Mahabharatam", te: "మహాభారతం" }, subtitle: { en: "Explore questions of dharma through the lives and choices of the Mahabharata.", te: "మహాభారత పాత్రల జీవితం, నిర్ణయాల ద్వారా ధర్మాన్ని తెలుసుకోండి." }, sections: [{ title: { en: "An epic for reflection", te: "ఆలోచనకు ఇతిహాసం" }, paragraphs: [{ en: "The Mahabharata brings together family, duty, friendship and the complexity of moral choices. Browse the Peetham's related talks and reading resources.", te: "మహాభారతం కుటుంబం, కర్తవ్యం, స్నేహం, నైతిక నిర్ణయాల సంక్లిష్టతను చూపిస్తుంది. పీఠం ప్రవచనాలు, పఠన వనరులను చూడండి." }] }], related: ["pravachanalu", "dharma", "books"] },
