// Individual stotra and sloka entries use a shared reading-page layout.
for (const [key, page] of Object.entries(window.SITE_PAGES)) {
  if (!page || !page.items) continue;
  for (const item of page.items) {
    if (!item.route || window.SITE_PAGES[item.route]) continue;
    if (item.route.startsWith("stotra-") || item.route.startsWith("sloka-")) {
      window.SITE_PAGES[item.route] = {
        kind: "resource", category: page.title,
        title: item.title, subtitle: item.description,
        resourceTag: item.tag,
        description: { en: "This resource belongs to the Sri Pranava Peetham devotional collection. Explore the related reading paths and study materials below.", te: "ఈ వనరు శ్రీ ప్రణవపీఠం భక్తి సేకరణలో భాగం. సంబంధిత పఠన మార్గాలు, అధ్యయన వనరులను క్రింద చూడండి." },
        related: [key, "sadhanalu", "pravachanalu"]
      };
    }
  }
}

for (const [key, page] of Object.entries(window.SITE_PAGES)) {
  if (!page || !page.related) continue;
  page.related = page.related.filter((slug) => window.SITE_PAGES[slug]);
}

