for (const [en, te, route, sourceSlug, icon, groupEn, groupTe, descEn, descTe, related] of dharmaSandehaluCategories) {
  const topics = (dharmaTopicSeeds[route] || ["General|సాధారణ"]).map((pair) => pair.split("|"));
  const items = topics.map(([topicEn, topicTe], index) => {
    const topicSlug = `${route}-topic-${index + 1}`;
    const title = { en: topicEn, te: topicTe };
    window.SITE_PAGES[topicSlug] = {
      kind: "dharma-topic",
      route: topicSlug,
      category: { en, te },
      title,
      subtitle: { en: `A local topic page in the ${en} Dharma Sandehalu archive.`, te: `${te} ధర్మ సందేహాల స్థానిక విభాగంలోని అంశం.` },
      categoryRoute: route,
      related: [route, "dharma"]
    };
    return { title, description: { en: `Browse local Dharma Sandehalu entries filed under ${topicEn}.`, te: `${topicTe} అంశం కింద ఉన్న స్థానిక ధర్మ సందేహాలను చూడండి.` }, tag: { en: groupEn, te: groupTe }, route: topicSlug, icon: "◉" };
  });
  window.SITE_PAGES[route] = {
    kind: "dharma-category",
    category: { en: "Dharma Sandehalu", te: "ధర్మ సందేహాలు" },
    title: { en, te },
    subtitle: { en: descEn, te: descTe },
    group: { en: groupEn, te: groupTe },
    icon,
    items,
    related: ["dharma", ...related]
  };
}

// Replace the short starter list with every entry from the original Stotras archive.
if (Array.isArray(window.STOTRA_ARCHIVE)) {
  const archive = window.STOTRA_ARCHIVE;
  const archiveRoutes = new Set(archive.map((entry) => entry.route));
  for (const route of Object.keys(window.SITE_PAGES)) {
    if (route.startsWith("stotra-") && !archiveRoutes.has(route)) delete window.SITE_PAGES[route];
  }
  const stotrasPage = window.SITE_PAGES.stotras;
  stotrasPage.items = archive.map((entry) => ({
    title: { en: entry.en, te: entry.te || entry.en },
    description: {
      en: `${entry.category} devotional reading from the Sri Pranava Peetham Stotras archive.`,
      te: `శ్రీ ప్రణవపీఠం స్తోత్రాల సేకరణలోని ${entry.categoryTe || entry.category} భక్తి పఠనం.`
    },
    tag: { en: entry.category, te: entry.categoryTe || entry.category },
    deity: entry.category,
    route: entry.route,
    href: entry.href,
    sourceUrl: entry.sourceUrl,
    pdfs: entry.pdfs || [],
    icon: "✿"
  }));
  for (const entry of archive) {
    window.SITE_PAGES[entry.route] = {
      kind: "stotra",
      category: { en: "Stotras", te: "స్తోత్రాలు" },
      title: { en: entry.en, te: entry.te || entry.en },
      subtitle: { en: `${entry.category} · Stotras archive`, te: `${entry.categoryTe || entry.category} · స్తోత్రాల సేకరణ` },
      description: {
        en: "This item is part of the searchable Stotras archive. Read the PDF here when one is available, or open the source page for its online text.",
        te: "ఇది వెతకగల స్తోత్రాల సేకరణలోని అంశం. పీడీఎఫ్ అందుబాటులో ఉంటే ఇక్కడే చదవండి; లేకపోతే ఆన్‌లైన్ పాఠ్యం కోసం మూల పుటను తెరవండి."
      },
      deity: entry.category,
      pdfs: entry.pdfs || [],
      sourceUrl: entry.sourceUrl || entry.href,
      related: ["stotras", "pravachanalu", "dharma"]
    };
  }
}

