const booksPage = window.SITE_PAGES.books;
if (booksPage) {
  const existingBookItems = booksPage.items || [];
  const shopItems = shopCatalog.map(([en, te, route, tagEn, tagTe], index) => ({
    title: { en, te },
    description: { en: `Browse this title in the Sri Pranava Peetham local book library. Ordering and payment are not connected in this preview.`, te: `శ్రీ ప్రణవపీఠం స్థానిక పుస్తక గ్రంథాలయంలో ఈ గ్రంథాన్ని చూడండి. ఈ ప్రివ్యూలో ఆర్డర్, చెల్లింపు సదుపాయాలు లేవు.` },
    tag: { en: tagEn, te: tagTe },
    route,
    icon: ["▤", "✿", "ॐ", "✧"][index % 4]
  }));
  const shopRoutes = new Set(shopItems.map((item) => item.route));
  booksPage.items = [...shopItems, ...existingBookItems.filter((item) => !shopRoutes.has(item.route))];
  for (const [en, te, route, tagEn, tagTe] of shopCatalog) {
    const existing = window.SITE_PAGES[route];
    window.SITE_PAGES[route] = {
      ...(existing || {}),
      kind: "book",
      category: { en: "Books for sale", te: "అమ్మకానికి పుస్తకాలు" },
      title: { en, te },
      subtitle: { en: `${tagEn} · Sri Pranava Peetham book shop`, te: `${tagTe} · శ్రీ ప్రణవపీఠం పుస్తక దుకాణం` },
      description: { en: "Browse this title in the local Sri Pranava Peetham book library. Ordering, payment and stock information are not connected in this preview.", te: "శ్రీ ప్రణవపీఠం స్థానిక పుస్తక గ్రంథాలయంలో ఈ గ్రంథాన్ని చూడండి. ఈ ప్రివ్యూలో ఆర్డర్, చెల్లింపు, నిల్వ వివరాల సదుపాయాలు లేవు." },
      related: ["books", "stotras", "pravachanalu"]
    };
  }
}

